"""Disposable git workspaces for eval runs.

After an agent runs, it controls the workspace, including .git/config and .gitattributes, which can make git
run commands. So changes are measured in Python against the original fixture, and the only git command run
afterwards is a commit count with hooks and fsmonitor turned off.
"""

from __future__ import annotations

import difflib
import os
import shutil
import subprocess
import tempfile
from pathlib import Path

# Generated by running code or by Finder; not part of an agent's change.
IGNORED_NAMES = {".git", "__pycache__", ".DS_Store"}


def git(workspace: Path, *args: str) -> str:
    """Run git in a workspace the agent has not touched yet, or in the HolyCow repository."""
    return subprocess.run(["git", *args], cwd=workspace, check=True, capture_output=True, text=True).stdout


def create(fixture: Path, parent: Path | None = None) -> Path:
    """Copy the fixture into a new temporary directory and commit it as the starting state."""
    workspace = Path(tempfile.mkdtemp(prefix="holycow-eval-", dir=parent)).resolve()
    if fixture.is_dir():
        shutil.copytree(fixture, workspace, dirs_exist_ok=True)
    git(workspace, "init", "-q", "-b", "main")
    git(workspace, "config", "user.name", "HolyCow Eval")
    git(workspace, "config", "user.email", "eval@holycow.invalid")
    git(workspace, "add", "-A")
    git(workspace, "commit", "-q", "--allow-empty", "-m", "Fixture")
    return workspace


def install_skills(workspace: Path, skill_dir: str, skills_dir: Path, names: list) -> list:
    """Copy skills into the agent's project-level skill folder, hidden from git status."""
    target = workspace / skill_dir
    target.mkdir(parents=True, exist_ok=True)
    for name in names:
        shutil.copytree(skills_dir / name, target / name)
    with (workspace / ".git" / "info" / "exclude").open("a") as exclude:
        exclude.write(f"/{skill_dir}/\n")
    return sorted(names)


def snapshot(folder: Path, skip=()) -> dict:
    """Relative path to file bytes. Symlinks are recorded by target and never followed."""
    files = {}
    if not folder.is_dir():
        return files
    skip = {path.strip("/") for path in skip}
    for current, dirs, names in os.walk(folder):
        prefix = Path(current).relative_to(folder).as_posix()
        prefix = "" if prefix == "." else prefix + "/"
        kept = []
        for name in dirs:
            path = Path(current) / name
            if name in IGNORED_NAMES or prefix + name in skip:
                continue
            if path.is_symlink():
                files[prefix + name] = b"symlink -> " + os.fsencode(os.readlink(path))
            else:
                kept.append(name)
        dirs[:] = kept
        for name in names:
            path = Path(current) / name
            if name in IGNORED_NAMES:
                continue
            if path.is_symlink():
                files[prefix + name] = b"symlink -> " + os.fsencode(os.readlink(path))
            elif path.is_file():
                files[prefix + name] = path.read_bytes()
    return files


def changes(fixture: Path, workspace: Path, skip=()) -> tuple:
    """Files added, changed or deleted relative to the fixture, and a unified diff of them.

    Committed changes count too, because the comparison is with the fixture rather than HEAD.
    """
    before, after = snapshot(fixture), snapshot(workspace, skip)
    changed = sorted(path for path in before.keys() | after.keys() if before.get(path) != after.get(path))
    return changed, "".join(_file_diff(path, before.get(path), after.get(path)) for path in changed)


def _file_diff(path: str, old, new) -> str:
    source = f"a/{path}" if old is not None else "/dev/null"
    target = f"b/{path}" if new is not None else "/dev/null"
    try:
        old_lines = (old or b"").decode().splitlines(keepends=True)
        new_lines = (new or b"").decode().splitlines(keepends=True)
    except UnicodeDecodeError:
        return f"Binary files {source} and {target} differ\n"
    lines = difflib.unified_diff(old_lines, new_lines, fromfile=source, tofile=target)
    return "".join(line if line.endswith("\n") else line + "\n" for line in lines)


def commits_added(workspace: Path):
    """Commits made on top of the fixture, or None if git cannot tell."""
    env = {
        "PATH": os.environ.get("PATH", "/usr/bin:/bin"),
        "HOME": str(workspace),
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_CONFIG_GLOBAL": os.devnull,
    }
    argv = ["git", "-c", "core.fsmonitor=false", "-c", "core.hooksPath=/dev/null", "rev-list", "--count", "HEAD"]
    try:
        result = subprocess.run(argv, cwd=workspace, env=env, capture_output=True, text=True, timeout=30, check=True)
        return int(result.stdout.strip()) - 1
    except (subprocess.SubprocessError, ValueError, OSError):
        return None


def skills_revision(root: Path) -> dict:
    """The repository commit the skills came from, and whether skills/ had uncommitted changes."""
    try:
        commit = git(root, "rev-parse", "HEAD").strip()
        dirty = bool(git(root, "status", "--porcelain", "--", "skills").strip())
    except (subprocess.CalledProcessError, FileNotFoundError):
        return {"commit": None, "dirty": None}
    return {"commit": commit, "dirty": dirty}
